#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLightNode: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = LightNode

    public static func lift(_ handle: UInt64) throws -> LightNode {
        return LightNode(unsafeFromHandle: handle)
    }

    public static func lower(_ value: LightNode) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LightNode {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
