/**
 * Failure modes of the derivation helpers.
 */
public 
enum DerivationError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The recovery phrase failed word-list, word-count, or checksum validation.
     */
    case InvalidMnemonic(msg: String
    )
    /**
     * A raw secret was not 32 bytes of hex.
     */
    case BadSecretLength(got: UInt32
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension DerivationError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDerivationError: FfiConverterRustBuffer {
    typealias SwiftType = DerivationError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DerivationError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidMnemonic(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 2: return .BadSecretLength(
            got: try FfiConverterUInt32.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DerivationError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidMnemonic(msg):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .BadSecretLength(got):
            writeInt(&buf, Int32(2))
            FfiConverterUInt32.write(got, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeDerivationError_lift(_ buf: RustBuffer) throws -> DerivationError {
    return try FfiConverterTypeDerivationError.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeDerivationError_lower(_ value: DerivationError) -> RustBuffer {
    return FfiConverterTypeDerivationError.lower(value)
}


/**
 * Why a [`LightNode`] operation failed.
 */
public 
enum LightNodeError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case AlreadyInitialized
    case Hex(field: String
    )
    case Invalid(msg: String
    )
    case InsufficientFunds(needed: UInt64
    )
    case BadSecretLength(expected: UInt32, got: UInt32
    )
    case Node(msg: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension LightNodeError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLightNodeError: FfiConverterRustBuffer {
    typealias SwiftType = LightNodeError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LightNodeError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .AlreadyInitialized
        case 2: return .Hex(
            field: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Invalid(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 4: return .InsufficientFunds(
            needed: try FfiConverterUInt64.read(from: &buf)
            )
        case 5: return .BadSecretLength(
            expected: try FfiConverterUInt32.read(from: &buf), 
            got: try FfiConverterUInt32.read(from: &buf)
            )
        case 6: return .Node(
            msg: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: LightNodeError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .AlreadyInitialized:
            writeInt(&buf, Int32(1))
        
        
        case let .Hex(field):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(field, into: &buf)
            
        
        case let .Invalid(msg):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .InsufficientFunds(needed):
            writeInt(&buf, Int32(4))
            FfiConverterUInt64.write(needed, into: &buf)
            
        
        case let .BadSecretLength(expected,got):
            writeInt(&buf, Int32(5))
            FfiConverterUInt32.write(expected, into: &buf)
            FfiConverterUInt32.write(got, into: &buf)
            
        
        case let .Node(msg):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(msg, into: &buf)
            
        }
    }
}


